const ROLE_INCONNU = '{{ROLE_INCONNU_ID}}';
const MAX_NOUVEAUX_PAR_SEMAINE = 20;
const now = new Date();
const FOUR_WEEKS_MS = 28 * 24 * 60 * 60 * 1000;

const discordItems = $('Récupérer membres Discord').all();
const discordMembers = discordItems.map(item => item.json);

const sheetItems = $('Récupérer Google Sheet').all();
const sheetData = sheetItems.map(item => item.json).filter(item => item.userId);

const accueillisIds = new Set(sheetData.map(s => String(s.userId)));

const allDiscordMemberIds = new Set(
  discordMembers.filter(m => m.user && !m.user.bot).map(m => m.user.id)
);

const tousNouveaux = [];
const aKick = [];
const aNettoyer = [];

for (const member of discordMembers) {
  if (!member.roles || !member.roles.includes(ROLE_INCONNU)) continue;
  if (member.user && member.user.bot) continue;
  const userId = member.user.id;
  if (!accueillisIds.has(userId)) {
    tousNouveaux.push({
      userId: userId,
      username: member.user.username,
      globalName: member.user.global_name || member.user.username,
      joinedAt: member.joined_at
    });
  }
}

tousNouveaux.sort((a, b) => new Date(a.joinedAt) - new Date(b.joinedAt));
const nouveaux = tousNouveaux.slice(0, MAX_NOUVEAUX_PAR_SEMAINE);
const reportes = tousNouveaux.length - nouveaux.length;

const membresInconnusIds = new Set(
  discordMembers
    .filter(m => m.roles && m.roles.includes(ROLE_INCONNU) && m.user && !m.user.bot)
    .map(m => m.user.id)
);

for (const entry of sheetData) {
  const dateLimite = new Date(entry.dateLimite);
  const entryUserId = String(entry.userId);
  if (!allDiscordMemberIds.has(entryUserId)) {
    aNettoyer.push({userId: entry.userId, username: entry.username, dateLimite: entry.dateLimite, raison: 'parti'});
  } else if (now >= dateLimite && membresInconnusIds.has(entryUserId)) {
    aKick.push({userId: entry.userId, username: entry.username, dateLimite: entry.dateLimite});
  } else if (!membresInconnusIds.has(entryUserId) && allDiscordMemberIds.has(entryUserId)) {
    aNettoyer.push({userId: entry.userId, username: entry.username, dateLimite: entry.dateLimite, raison: 'devenu_membre'});
  }
}

const dateLimite = new Date(now.getTime() + FOUR_WEEKS_MS);
const dateLimiteStr = dateLimite.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long' });
const dateAccueilStr = now.toISOString().split('T')[0];
const dateLimiteISO = dateLimite.toISOString().split('T')[0];

return [{json: {nouveaux, aKick, aNettoyer, nombreNouveaux: nouveaux.length, nombreAKick: aKick.length, nombreANettoyer: aNettoyer.length, reportes, dateLimiteStr, dateAccueilStr, dateLimiteISO}}];
